 sources=''
 if g['sources']:sources='<section class="sources"><h2>Sources & further reading</h2><ul>'+''.join(f'<li><a href="{u}" target="_blank" rel="noopener noreferrer">{escape(t)}</a></li>' for t,u in g['sources'])+'</ul><p>Official reference material checked 2 November 2026. The planning advice and examples above are Deskwise editorial guidance.</p></section>'
